const __pageData = JSON.parse('{"title":"Israel","description":"","frontmatter":{"title":"Israel","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["israel","middle-east","iran","netanyahu","geopolitics"],"sources":["raw/and-iran-iran-so-far-away.md","raw/assad-day-in-damascus.md","raw/badlands-brief-07c.md","raw/badlands-brief-029.md","raw/badlands-brief-0fb.md","raw/badlands-brief-0bd.md","raw/badlands-brief-165.md","raw/badlands-brief-095.md","raw/badlands-brief-05f.md","raw/badlands-brief-174.md","raw/badlands-brief-25c.md","raw/badlands-brief-1c6.md","raw/badlands-brief-282.md","raw/badlands-brief-2c5.md","raw/badlands-brief-52f.md","raw/badlands-brief-5a2.md","raw/badlands-brief-625.md","raw/badlands-brief-6b4.md","raw/badlands-brief-6f0.md","raw/badlands-brief-6f4.md","raw/badlands-brief-739.md","raw/badlands-brief-7bf.md","raw/badlands-brief-884.md","raw/badlands-brief-8c2.md","raw/badlands-brief-9ac.md","raw/badlands-brief-9ea.md","raw/badlands-brief-861.md","raw/badlands-brief-774.md","raw/badlands-brief-98d.md","raw/badlands-brief-bb1.md","raw/badlands-brief-b62.md","raw/badlands-brief-b56.md","raw/badlands-brief-c07.md","raw/badlands-brief-e9e.md","raw/badlands-brief-f62.md","raw/badlands-news-brief-065.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-109.md","raw/badlands-news-brief-0b0.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-13f.md","raw/badlands-news-brief-158.md","raw/badlands-news-brief-1a0.md","raw/badlands-news-brief-1c3.md","raw/badlands-news-brief-1d1.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-2db.md","raw/badlands-news-brief-2f2.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-447.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-565.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-574.md","raw/badlands-news-brief-7bf.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/israel.md","filePath":"entities/israel.md","lastUpdated":null}');
